INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$More ticket sales might or might not make the route viable. The pundit does not assume that they will; the town officials' recommendation suggests that possibility. The pundit's flaw is dismissing their advice by pointing to their behavior.$batch01$), ($batch01$B$batch01$, $batch01$The airline may have options besides suspension and continued losses. The pundit's inference about whether residents should follow the recommendation does not rely on a two-option view of the airline's choices.$batch01$), ($batch01$C$batch01$, $batch01$Who paid for the officials' trip does not determine whether encouraging residents to fly is sound advice.$batch01$), ($batch01$D$batch01$, $batch01$A general comparison of ground and air transport prices would not establish that the officials' advice should be ignored. The route's profitability is the relevant issue.$batch01$), ($batch01$E$batch01$, $batch01$The pundit uses the officials' failure to follow their own recommendation as the reason to reject the recommendation. That is a version of the ad hominem mistake: hypocrisy can be real while the advice remains sound.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT114-S1-Q8$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
